// All application data is synthetic. One n8n Code node, no external modules.
const request = $input.first().json || {};
const query = request.query || {};
const action = String(query.action || 'ui').toLowerCase();
const validId = id => /^\d{6,12}$/.test(String(id));
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeExcel = x => {let s=String(x??'');return /^[\s\x00-\x1f]*[=+\-@]/.test(s)?"'"+s:s;};
const pct = x => x === null || x === undefined ? 'N/A' : Number(x).toFixed(2)+'%';
const studentProfile = function(requestedId) {

/**
 * FYP SMART ATTENDANCE SYSTEM
 * 100 EMULATED STUDENT PROFILES
 *
 * n8n Code node: Student Profile Emulation
 * Mode: Run Once for All Items
 *
 * Student IDs: 900000001 - 900000100
 *
 * All generated data is synthetic.
 * No database or Qwickly write operations.
 */

const req = { query: { sis_id: requestedId } };

const sisId = String(
  req.query?.sis_id ??
  req.query?.sisId ??
  req.body?.sis_id ??
  ''
).trim();

// 1. Validate student ID
if (!/^\d{6,12}$/.test(sisId)) {
  return [{
    json: {
      success: false,
      isSynthetic: true,
      message: 'Provide a numeric sis_id (6–12 digits).'
    }
  }];
}

// 2. Identify the demonstration student
const found = /^900000(\d{3})$/.exec(sisId);
let number = found ? Number(found[1]) : null;

// Keep previously used development IDs working
if (sisId === '104404156') number = 101;
if (sisId === '100000001') number = 102;

if (
  number === null ||
  number < 1 ||
  (found && number > 100)
) {
  return [{
    json: {
      success: false,
      isSynthetic: true,
      sisId,
      message: 'Student not found in the demo dataset.'
    }
  }];
}

// 3. Fictional student names
const firstNames = [
  'Aina', 'Daniel', 'Siti', 'Adam',
  'Mei Ling', 'Amir', 'Grace', 'Farah',
  'Jason', 'Nurul', 'Ryan', 'Hana',
  'Kelvin', 'Nadia', 'David', 'Izzah',
  'Sarah', 'Hakim', 'Michelle', 'Afiq'
];

const lastNames = [
  'Rahman', 'Tan', 'Lim', 'Abdullah',
  'Lee', 'Wong', 'Ismail', 'Chong',
  'Aziz', 'Ong', 'Yusof', 'Ng',
  'Hassan', 'Goh', 'Ibrahim', 'Chan'
];

// 4. Demonstration programmes and units
// Unit names/codes are sample fixtures,
// not verified university catalogue information.
const programmes = [
  {
    code: 'BCS',
    name: 'Bachelor of Computer Science',
    durationYears: 3,
    units: [
      ['COS10022', 'Introduction to Programming'],
      ['COS20019', 'Cloud Computing Architecture'],
      ['COS20031', 'Computer Systems'],
      ['SWE30003', 'Software Engineering Project'],
      ['COS30045', 'Data Analytics'],
      ['COS30049', 'Computing Project'],
      ['ICT10001', 'Information Technology Fundamentals'],
      ['MAT10001', 'Mathematics for Computing'],
      ['STA10001', 'Statistics Fundamentals']
    ]
  },
  {
    code: 'BICT',
    name: 'Bachelor of Information and Communication Technology',
    durationYears: 3,
    units: [
      ['ICT10001', 'IT Fundamentals'],
      ['NET10001', 'Network Fundamentals'],
      ['ICT10002', 'Introduction to Databases'],
      ['NET20001', 'Routing and Switching'],
      ['SEC20001', 'Network Security'],
      ['ICT20003', 'Systems Administration'],
      ['NET30001', 'Enterprise Networks'],
      ['ICT30002', 'IT Project'],
      ['SEC30001', 'Cybersecurity Practice']
    ]
  },
  {
    code: 'BBUS',
    name: 'Bachelor of Business',
    durationYears: 3,
    units: [
      ['BUS10001', 'Business Fundamentals'],
      ['MGT10001', 'Management Principles'],
      ['ACC10001', 'Financial Accounting'],
      ['ECO20001', 'Business Economics'],
      ['MKT20001', 'Marketing Management'],
      ['BUS20001', 'Business Analytics'],
      ['FIN30001', 'Corporate Finance'],
      ['MGT30001', 'Strategic Management'],
      ['BUS30001', 'Business Project']
    ]
  }
];

// 5. Generate this student's identity
const seq = number;
const prog = programmes[(seq - 1) % programmes.length];

const firstName =
  number === 101 ? 'Fredly Benny' :
  number === 102 ? 'Test' :
  firstNames[(seq - 1) % firstNames.length];

const lastName =
  number === 101 ? 'Anak Vilen' :
  number === 102 ? 'Student' :
  lastNames[(seq * 7 + 3) % lastNames.length];

const fullName = number <= 100
  ? `${firstName} ${lastName} (Demo ${String(number).padStart(3, '0')})`
  : `${firstName} ${lastName}`;

// 6. Emulated international student classification
const international =
  seq % 4 === 0 || seq % 7 === 0;

const visaReview =
  international && seq % 5 === 0;

const visaExpiry = international
  ? (visaReview ? '2026-12-15' : '2028-06-30')
  : null;

// 7. Create enrolments for three semesters
// These IDs match the existing semester emulator.
const semesterIds = [
  '2025-S1',
  '2025-S2',
  '2026-S1'
];

const enrolments = prog.units.map(
  ([code, name], idx) => ({
    unitId: `${sisId}-${code}`,
    code,
    name,
    semester: semesterIds[Math.floor(idx / 3)],
    enrolmentStatus: 'Enrolled',
    source: 'DEMO_SYNTHETIC'
  })
);

// 8. Build the student profile
const student = {
  studentId: `DEMO-${sisId}`,
  sisId,

  firstName,
  lastName,
  fullName,

  email: number === 101
    ? '104404156@students.swinburne.edu.my'
    : `demo.student${String(seq).padStart(3, '0')}@example.invalid`,

  studentType: international
    ? 'International'
    : 'Local',

  campus: 'Swinburne Sarawak (Demo)',
  faculty: 'Demonstration Faculty',

  programme: {
    code: prog.code,
    name: prog.name,
    durationYears: prog.durationYears
  },

  yearOfStudy: 2,
  semester: '2026-S1',

  academicStatus:
    seq % 13 === 0
      ? 'On leave (Demo)'
      : 'Active (Demo)',

  enrolments,

  visa: {
    applicable: international,

    status: international
      ? (
          visaReview
            ? 'Review required (Demo)'
            : 'Active (Demo)'
        )
      : 'Not applicable',

    expiryDate: visaExpiry,
    reviewRequired: visaReview,
    isSynthetic: true,

    note:
      'SIMULATED DATA ONLY. ' +
      'Not a verified visa or immigration assessment.'
  },

  isSynthetic: true
};

// 9. Return the JSON response
return [{
  json: {
    success: true,
    student,
    isSynthetic: true,
    source: 'STUDENT_PROFILE_EMULATOR',
    message:
      'Synthetic student profile for demonstration only.'
  }
}];

};
function semesterData(id){
  // The original uploaded file includes no complete semester emulator branch.
  // These numbers are explicitly synthetic and never labelled Qwickly-verified.
  const last=Number(id.slice(-1))||0;
  const seeds=[82+(last%11),84+(last%9),88+((last*3)%8)];
  return [
    {semesterId:'2025-S1',label:'Semester 1, 2025',intake:'2025',startDate:'2025-02-01',endDate:'2025-06-30',percentage:Math.min(99,seeds[0]),source:'DEMO_SYNTHETIC',calculationMethod:'Deterministic emulator fixture'},
    {semesterId:'2025-S2',label:'Semester 2, 2025',intake:'2025',startDate:'2025-07-01',endDate:'2025-12-31',percentage:Math.min(99,seeds[1]),source:'DEMO_SYNTHETIC',calculationMethod:'Deterministic emulator fixture'},
    {semesterId:'2026-S1',label:'Semester 1, 2026',intake:'2026',startDate:'2026-02-01',endDate:'2026-06-30',percentage:Math.min(99,seeds[2]),source:'DEMO_SYNTHETIC',calculationMethod:'Deterministic emulator fixture'}
  ];
}
function reportFor(id){
  if(!validId(id)) throw Error('Enter a numeric SIS ID (6–12 digits).');
  const result=studentProfile(id)[0].json;
  if(!result.success || !result.student) throw Error(result.message || 'Student not found in the demo dataset.');
  const profile=result.student;
  const semesters=semesterData(id);
  return {success:true,student:{sisId:id},semesters,source:'DEMO_SYNTHETIC',isSynthetic:true,profile,profileSource:'STUDENT_PROFILE_EMULATOR',unitBreakdown:unitBreakdown(id,profile,semesters)};
}
function hash(value){let h=2166136261;for(const c of value){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function key(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function unitBreakdown(id, profile, semesters){
 return semesters.map((s,i)=>{
  const units=[];
  for(const en of (profile.enrolments||[])){
   const value=en.semester || '';
   const match=[s.semesterId,s.label,s.intake].some(v=>key(v)===key(value) || (key(v).length>5 && key(value).includes(key(v))));
   const fallsBack=!match && i===semesters.length-1 && !semesters.some(x=>[x.semesterId,x.label,x.intake].some(v=>key(v)===key(value)||(key(v).length>5&&key(value).includes(key(v)))));
   if(!match&&!fallsBack)continue;
   const code=en.code||en.unitId||'Unknown';
   const weeks=Array.from({length:12},(_,i)=>{
      const week=i+1,base=hash(`${id}|${s.semesterId}|${code}|${week}`);
      const classScore=base%11<9?1:0,labScore=Math.floor(base/13)%11<9?1:0,weekScore=(classScore+labScore)/2;
      return {week,classStatus:classScore?'Present':'Absent',labStatus:labScore?'Present':'Absent',classScore,labScore,weekScore,weekPercent:weekScore*100,source:'DEMO_WEEKLY_FIXTURE'};
   });
   units.push({code,name:en.name||code,semesterId:s.semesterId,semesterLabel:s.label,
     semesterAssignment:match?'MATCHED_EMULATED_ENROLMENT':'DEMO_CURRENT_ENROLMENT_ASSIGNMENT',
     percentage:Math.round(weeks.reduce((sum,w)=>sum+w.weekScore,0)/12*10000)/100,weekCount:12,weeks,source:'DEMO_WEEKLY_FIXTURE'});
  }
  return {semesterId:s.semesterId,semesterLabel:s.label,semesterPercentage:s.percentage,semesterSource:s.source,units,
   note:'Unit and weekly data are illustrative fixtures, not Qwickly attendance; semester percentages come from an independent emulated series.'};
 });
}
function batchFrom(s){
 const ids=Array.from(new Set(String(s||'').split(/[\s,;]+/).map(s=>s.trim()).filter(Boolean)));
 if(!ids.length||ids.length>25)throw Error('Provide 1–25 SIS IDs.');
 if(ids.some(id=>!validId(id)))throw Error('Every SIS ID must be numeric, 6–12 digits.');
 return ids.map(sisId=>{try{const data=reportFor(sisId);return {sisId,data,unitBreakdown:data.unitBreakdown};}catch(e){return {sisId,error:e.message};}});
}
function csvFor(d){
 const csv=x=>'"'+safeExcel(x).replace(/"/g,'""')+'"';
 const rows=[['sis_id','student_name','semester','intake','attendance_percentage','attendance_source','profile_source','report_status']];
 for(const s of d.semesters)rows.push([d.profile.sisId,d.profile.fullName,s.label,s.intake,s.percentage??'',s.source,'STUDENT_PROFILE_EMULATOR','DEMONSTRATION_ONLY_NOT_ISSUED']);
 return '\ufeff'+rows.map(row=>row.map(csv).join(',')).join('\r\n')+'\r\n';
}
function workbookRows(results){
 const students=[],semesters=[],units=[],weeks=[],errors=[];
 for(const row of results){if(!row.data){errors.push([row.sisId,row.error||'Unknown error']);continue;}
 const d=row.data;
 students.push([d.profile.sisId,d.profile.fullName,d.profile.email,d.profile.programme.name,d.profile.studentType,d.profile.visa.status,'Emulated Profile']);
 for(const s of d.semesters) semesters.push([d.profile.sisId,d.profile.fullName,s.label,s.intake,s.percentage,s.source,s.calculationMethod,'Semester source and weekly fixtures are independent']);
 for(const sem of d.unitBreakdown)for(const u of sem.units){
   units.push([d.profile.sisId,d.profile.fullName,sem.semesterLabel,u.code,u.name,u.percentage,u.weekCount,'Demo weekly data',u.semesterAssignment]);
   for(const w of u.weeks)weeks.push([d.profile.sisId,d.profile.fullName,sem.semesterLabel,u.code,w.week,w.classStatus,w.labStatus,w.classScore,w.labScore,w.weekScore,w.weekPercent,'Demo weekly data']);
 }
 }
 return [
 {name:'Students',headers:['Student ID','Student Name','Email','Programme','Student Type','Visa Status','Data Source'],rows:students},
 {name:'Semesters',headers:['Student ID','Student Name','Semester','Intake','Attendance %','Data Source','Calculation','Note'],rows:semesters},
 {name:'Units',headers:['Student ID','Student Name','Semester','Unit Code','Unit Name','Attendance %','Weeks','Data Source','Semester Mapping'],rows:units},
 {name:'Weekly Checks',headers:['Student ID','Student Name','Semester','Unit Code','Week','Class','Lab','Class Score','Lab Score','Week Score','Week %','Data Source'],rows:weeks},
 {name:'Errors',headers:['Student ID','Error'],rows:errors},
 {name:'Read Me',headers:['Item','Explanation'],rows:[
 ['STATUS','DEMONSTRATION DATA ONLY. NOT AN OFFICIAL ATTENDANCE OR VISA RECORD.'],
 ['Week Rule','Class present + Lab present = 1.0; only one present = 0.5; neither present = 0.0.'],
 ['Week %','Week Score multiplied by 100.'],
 ['Unit Attendance %','Average weekly score over illustrative 12 weeks, multiplied by 100.'],
 ['Semester Attendance %','Retrieved from the embedded deterministic synthetic emulator.'],
 ['Important','Demo unit/week scores are not reconciled to the independent semester percentage.'],
 ['Units','Names from the original student profile emulation, weekly statuses are synthetic fixture values.'],
 ['Missing Results','See Errors sheet. Missing results are never 0% attendance.'],
 ['Security','Do not publish student data without real administrative authentication.']
 ]}];
}

// Create multi-sheet XLSX without Node dependencies or paid n8n variables.
const utf8=s=>Buffer.from(String(s),'utf8');
function crc32(b){let c=0xffffffff;for(let i=0;i<b.length;i++){c^=b[i];for(let j=0;j<8;j++)c=(c&1)?(c>>>1)^0xedb88320:c>>>1;}return (c^0xffffffff)>>>0;}
function makeZip(entries){
 const chunks=[],central=[];let offset=0;
 for(const entry of entries){
  const fn=utf8(entry.name),value=Buffer.isBuffer(entry.data)?entry.data:utf8(entry.data),crc=crc32(value);
  const header=Buffer.alloc(30);header.writeUInt32LE(0x04034b50,0);header.writeUInt16LE(20,4);header.writeUInt16LE(0x0800,6);header.writeUInt16LE(0,8);header.writeUInt32LE(crc,14);header.writeUInt32LE(value.length,18);header.writeUInt32LE(value.length,22);header.writeUInt16LE(fn.length,26);
  chunks.push(header,fn,value);
  const ch=Buffer.alloc(46);ch.writeUInt32LE(0x02014b50,0);ch.writeUInt16LE(20,4);ch.writeUInt16LE(20,6);ch.writeUInt16LE(0x0800,8);ch.writeUInt32LE(crc,16);ch.writeUInt32LE(value.length,20);ch.writeUInt32LE(value.length,24);ch.writeUInt16LE(fn.length,28);ch.writeUInt32LE(offset,42);central.push(ch,fn);
  offset+=header.length+fn.length+value.length;
 }
 const center=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50,0);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(center.length,12);end.writeUInt32LE(offset,16);
 return Buffer.concat([...chunks,center,end]);
}
function xml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'');}
function makeXlsx(sheets){
 const entries=[
 {name:'[Content_Types].xml',data:'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>'+sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>'},
 {name:'_rels/.rels',data:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'},
 {name:'xl/workbook.xml',data:'<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+sheets.map((s,i)=>`<sheet name="${xml(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>'},
 {name:'xl/_rels/workbook.xml.rels',data:'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+`<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`},
 {name:'xl/styles.xml',data:'<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Aptos"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Aptos"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFC8102E"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'}
 ];
 for(let si=0;si<sheets.length;si++){
  const sh=sheets[si],all=[sh.headers,...sh.rows];
  let t='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="A1:'+(function(n){let s='';while(n){s=String.fromCharCode(65+(n-1)%26)+s;n=Math.floor((n-1)/26);}return s;})(sh.headers.length)+String(all.length)+'"/><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="17"/><cols>'+sh.headers.map((_,i)=>`<col min="${i+1}" max="${i+1}" width="${i<2?24:21}" customWidth="1"/>`).join('')+'</cols><sheetData>';
  for(let ri=0;ri<all.length;ri++){
   t+=`<row r="${ri+1}">`;
   for(let ci=0;ci<all[ri].length;ci++){
    const col=(function(n){let s='';while(n){s=String.fromCharCode(65+(n-1)%26)+s;n=Math.floor((n-1)/26);}return s;})(ci+1);
    const v=all[ri][ci],header=ri===0?' s="1"':'';
    if(ri>0&&typeof v==='number'&&Number.isFinite(v))t+=`<c r="${col}${ri+1}"${header}><v>${v}</v></c>`;
    else t+=`<c r="${col}${ri+1}" t="inlineStr"${header}><is><t xml:space="preserve">${xml(safeExcel(v))}</t></is></c>`;
   }
   t+='</row>';
  }
  t+='</sheetData><autoFilter ref="A1:'+ (function(n){let s='';while(n){s=String.fromCharCode(65+(n-1)%26)+s;n=Math.floor((n-1)/26);}return s;})(sh.headers.length)+'1"/></worksheet>';
  entries.push({name:`xl/worksheets/sheet${si+1}.xml`,data:t});
 }
 return makeZip(entries);
}

// Native, dependency-free PDF generator for n8n Cloud Code node.
// Reproduces the original A4 structure, headings, red/grey tables, amber compliance warning, page footers.
const JPG_B64='';
const JPG_W=300, JPG_H=598;
function makeReportPdf(d,kind){
  // Faithful A4 letter presentation. No unverified institutional signature or immigration conclusion.
  const PW=595.28, PH=841.89, M=67, RIGHT=PW-67, CW=RIGHT-M;
  const RED=[.77,.05,.16], INK=[.16,.18,.22], MUTE=[.35,.39,.44], WHITE=[1,1,1], PINK=[.97,.92,.93], GREY=[.95,.955,.965], BORDER=[.52,.53,.55];
  const safe=s=>String(s===undefined||s===null?'N/A':s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[\u2010-\u2015]/g,'-').replace(/[\u2018\u2019]/g,"'").replace(/[\u201c\u201d]/g,'"').replace(/[^\x20-\x7e]/g,'?');
  const escpdf=s=>'('+safe(s).replace(/[\\()]/g,'\\$&')+')';
  const co=x=>x.join(' ')+' rg', stroke=x=>x.join(' ')+' RG';
  let pages=[],current=null,y=0;
  function cmd(v){current.push(v);}
  function rect(x,by,w,h,fill,border){if(fill)cmd(`${co(fill)} ${x.toFixed(2)} ${by.toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re f`);if(border)cmd(`${stroke(border)} .55 w ${x.toFixed(2)} ${by.toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re S`);}
  function line(x1,y1,x2,y2,color=BORDER,width=.7){cmd(`${stroke(color)} ${width} w ${x1.toFixed(2)} ${y1.toFixed(2)} m ${x2.toFixed(2)} ${y2.toFixed(2)} l S`);}
  function text(str,x,by,size=9,bold=false,color=INK){cmd(`BT /${bold?'F2':'F1'} ${size} Tf ${co(color)} 1 0 0 1 ${x.toFixed(2)} ${by.toFixed(2)} Tm ${escpdf(str)} Tj ET`);}
  function wr(s,width,sz=8.5){const words=safe(s).split(/\s+/),out=[];let t='';for(const w of words){if(!w)continue;if((t+' '+w).trim().length*sz*.50>width&&t){out.push(t);t=w;}else t=(t?t+' ':'')+w;}if(t)out.push(t);return out.length?out:[''];}
  function page(){current=[];pages.push(current);cmd(`q 29 0 0 58 ${RIGHT-40} 735 cm /Im1 Do Q`);line(M-35,575,M-35,64,RED,3); y=705;
    if(pages.length>1){text('CONTINUED',M,PH-72,9,true,RED);y=PH-105;}}
  function ensure(h){if(y-h<88){page();}}
  function space(n){y-=n;}
  function info(label,value){const chunks=wr(value,RIGHT-(M+175)-4,8.6),h=Math.max(17,chunks.length*13+4);ensure(h+1);text(label,M+19,y,8.8,true);text(':',M+145,y,8.8);let yy=y;for(const chunk of chunks){text(chunk,M+163,yy,8.7);yy-=13;}space(h);}
