on>\n<button class=\"navLink\" data-page=\"settings\"><span class=\"navIcon\">⚙</span>Settings</button></nav>\n<div class=\"sidebarFoot\"><div class=\"sideCard\"><strong>Academic reporting</strong><p>Multi-student review workspace</p><span>● EMULATED DATA</span></div><div class=\"micro\" style=\"color:#b7c0cf;padding:18px 9px\">Standalone n8n Edition · Prototype</div></div></aside>\n<button class=\"backdrop\" id=\"backdrop\" style=\"display:none\" aria-label=\"Close navigation\"></button>\n<div class=\"main\"><header class=\"topbar\"><div class=\"topbarStart\"><button class=\"mobileNav\" id=\"menuBtn\">☰</button>Administration <span class=\"slash\">/</span> <strong id=\"crumb\">Overview</strong></div><div class=\"topbarEnd\"><span class=\"demoPill\">● Prototype</span><div class=\"account\">Administrator<small>n8n standalone — no Entra session</small></div><div class=\"avatar\">A</div></div></header>\n<main class=\"content\"><div class=\"pageHeader\"><div class=\"eyebrow\">SMART ACADEMIC ATTENDANCE</div><h1 id=\"pageTitle\">Overview<span>.</span></h1><p id=\"pageSubtitle\">Search, review and export demonstration student records.</p></div>\n<div class=\"notice\"><strong>Prototype / synthetic information:</strong> This portal contains demonstration records, not verified Qwickly, university or immigration data. <strong>Access control is not configured</strong>; do not publish this endpoint for real student records.</div>\n<div id=\"stage\"></div><footer class=\"footer\">Smart Academic Attendance System <span>Final Year Project · n8n Administrator Portal</span></footer></main></div></div>\n<script>\n'use strict';\nconst BASE=__BASE_URL__;\nconst initialPage=__INITIAL_PAGE__;\nconst initialIds=__INITIAL_IDS__;\nlet page='dashboard', results=[], idsInput=initialIds||'',selected=null,working=false;\nconst $=id=>document.getElementById(id);\nconst escapeHtml=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;','\\'':'&#39;'}[c]));\nconst score=x=>x==null?'N/A':Number(x).toFixed(2)+'%';\nfunction endpoint(action,params={}){const u=new URL(BASE);u.searchParams.set('action',action);for(const [k,v]of Object.entries(params))u.searchParams.set(k,String(v));return u.toString();}\nfunction title(n){return ({dashboard:'Overview',students:'Student Search',student:'Student Profile',attendance:'Attendance',visa:'Visa & Compliance',reports:'Reports & Excel',settings:'Settings'})[n]||'Overview';}\nfunction subtitle(n){return ({dashboard:'A dedicated workspace for searching students, reviewing attendance, checking visa context and exporting reports.',students:'Batch search student profiles and enrolments by SIS ID.',student:'Detailed emulated profile with attendance units and weekly Class/Lab drill-down.',attendance:'Compare semester attendance across multiple student IDs.',visa:'Review emulated visa information. No immigration status is assessed.',reports:'Create three separate PDF drafts (attendance, visa and compliance), CSV and six-sheet Excel workbooks.',settings:'Data sources, access control and prototype limitations.'})[n];}\nfunction setPage(n){page=n;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===n));$('pageTitle').innerHTML=escapeHtml(title(n))+'<span>.</span>';$('crumb').textContent=title(n);$('pageSubtitle').textContent=subtitle(n);$('sidebar').classList.remove('sidebarOpen');$('backdrop').style.display='none';render();}\nfunction panel(heading,body,detail=''){return `<section class=\"panel\"><div class=\"panelHead\"><div><h2>${heading}</h2>${detail?`<p>${detail}</p>`:''}</div></div>${body}</section>`;}\nfunction stat(label,v,note,red=false){return `<div class=\"kpi ${red?'redKpi':''}\"><span>${label}</span><strong>${v}</strong><small>${note}</small></div>`;}\nfunction go(n){selected=null;setPage(n);}\nfunction overview(){const cards=[['students','Student Search','Search up to 25 numeric SIS IDs, view results and profile details.'],['attendance','Attendance Records','Compare semester results; expand semester, unit and weekly scoring.'],['visa','Visa & Compliance','View synthetic visa details, without issuing any status decisions.'],['reports','Reports & Excel','Export separate PDF reports, CSV and XLSX workbooks.']];return `<div class=\"kpis\">${stat('Student Search','Batch','Up to 25 SIS IDs per lookup',true)}${stat('Semester → Unit','Drill-down','Expandable details')}${stat('Weekly Rule','0 / 0.5 / 1','Class + Lab example')}${stat('Audit exports','Excel','Six report sheets')}</div>`+panel('Select an administrative function',`<div class=\"intro-grid\">${cards.map(([p,t,d])=>`<button class=\"moduleCard\" data-open=\"${p}\"><h3>${t} →</h3><p>${d}</p></button>`).join('')}</div>`,'Each function has its own workspace, following the original portal navigation.')+panel('How the attendance calculation works',`<p>For an illustrative weekly unit with one Class and one Lab, each session contributes half the week’s possible credit.</p><div class=\"formula\">Class present + Lab present = 1.0 &nbsp; | &nbsp; Exactly one present = 0.5 &nbsp; | &nbsp; Both absent = 0.0</div><p class=\"footnote\">Weekly fixtures are synthetic and independent of the semester source.</p>`);}\nfunction workspace(){const names={students:'Find students',attendance:'Attendance overview',visa:'Visa review',reports:'Report exports'};return `<section class=\"panel\"><div class=\"panelHead\"><div><h2>${names[page]}</h2><p>Search multiple students in one request using the built-in synthetic n8n emulator.</p></div><span class=\"badge\">Up to 25 students</span></div><form id=\"batchForm\"><label for=\"ids\" class=\"inputLabel\">STUDENT SIS IDS (ONE PER LINE OR SEPARATED BY COMMAS)</label><textarea id=\"ids\" class=\"textarea\" rows=\"3\" placeholder=\"104404156&#10;900000001&#10;900000002\">${escapeHtml(idsInput)}</textarea><div class=\"row\" style=\"margin-top:15px\"><button class=\"button\" type=\"submit\" id=\"searchBtn\">⌕ &nbsp; Search Students</button><button type=\"button\" class=\"button secondaryButton\" id=\"excelBtn\">⇩ &nbsp; Export Excel (.xlsx)</button><span class=\"muted\">Valid demo IDs: 900000001–900000100 and 104404156.</span></div></form><p class=\"error\" id=\"formError\" style=\"display:none\" role=\"alert\"></p></section><div id=\"resultArea\">${results.length?resultTable():''}</div>`;}\nfunction resultTable(){const ok=results.filter(r=>r.data),fail=results.filter(r=>r.error),u=ok.reduce((n,r)=>n+r.data.unitBreakdown.reduce((t,s)=>t+s.units.length,0),0);return `<div class=\"kpis\">${stat('Requested',results.length,'Unique SIS IDs',true)}${stat('Loaded',ok.length,'Available results')}${stat('Errors',fail.length,'Shown individually')}${stat('Unit Fixtures',u,'Synthetic unit data')}</div>`+panel(page==='visa'?'Student visa review':page==='attendance'?'Semester attendance comparison':page==='reports'?'Available report formats':'Search results',`<div class=\"tableWrap\"><table class=\"table\"><thead><tr><th>Student ID</th><th>Student Name</th>${page==='visa'?'<th>Student Type</th><th>Visa Status</th>':page==='attendance'?'<th>Semesters</th><th>Latest Semester %</th>':page==='reports'?'<th>Attendance PDF</th><th>Visa PDF</th><th>Compliance PDF</th>':'<th>Programme</th><th>Semesters</th>'}<th>Action</th></tr></thead><tbody>${results.map(r=>{if(!r.data)return `<tr><td>${escapeHtml(r.sisId)}</td><td colspan=\"5\" style=\"color:#b21534\">${escapeHtml(r.error)}</td></tr>`;let d=r.data;return `<tr><td><strong>${escapeHtml(r.sisId)}</strong></td><td>${escapeHtml(d.profile.fullName)}</td>${page==='visa'?`<td>${escapeHtml(d.profile.studentType)}</td><td><span class=\"badge\">${escapeHtml(d.profile.visa.status)}</span></td>`:page==='attendance'?`<td>${d.semesters.length}</td><td><strong>${score(d.semesters.at(-1)?.percentage)}</strong></td>`:page==='reports'?`<td><button class=\"icon-button\" data-download=\"academic\" data-sis=\"${r.sisId}\">Attendance</button></td><td><button class=\"icon-button\" data-download=\"visa\" data-sis=\"${r.sisId}\">Visa</button></td><td><button class=\"icon-button\" data-download=\"compliance\" data-sis=\"${r.sisId}\">Compliance</button></td>`:`<td>${escapeHtml(d.profile.programme.name)}</td><td>${d.semesters.length}</td>`}<td><button class=\"icon-button\" data-student=\"${r.sisId}\">View student →</button></td></tr>`}).join('')}</tbody></table></div><p class=\"footnote\">Results use independent deterministic synthetic data only.</p>`,'Choose a student to expand their semester, unit and weekly records.');}\nfunction gridFields(entries){return `<div class=\"detailGrid\">${entries.map(([k,v])=>`<div class=\"detailField\"><small>${escapeHtml(k)}</small><strong>${escapeHtml(v??'N/A')}</strong></div>`).join('')}</div>`;}\nfunction badgePresence(v){return `<span class=\"badge ${v==='Present'?'greenBadge':'redBadge'}\">${escapeHtml(v)}</span>`;}\nfunction studentPage(){if(!selected)return panel('No student selected','<p>Select a student using Student Search.</p><button class=\"button\" data-open=\"students\">Go to Student Search</button>');const d=selected,p=d.profile;\n const fields=[['Student ID',p.sisId],['Full name',p.fullName],['Email',p.email],['Programme',p.programme.name],['Programme code',p.programme.code],['Year',p.yearOfStudy],['Faculty',p.faculty],['Campus',p.campus],['Student type',p.studentType],['Academic status',p.academicStatus]];\n const terms=d.semesters.map((s,i)=>{let breakdown=d.unitBreakdown.find(x=>x.semesterId===s.semesterId);return `<details class=\"accordion\" ${i===d.semesters.length-1?'open':''}><summary><span><strong>${escapeHtml(s.label)}</strong><div class=\"micro\">${escapeHtml(s.intake)} · Demo semester result</div></span><span><strong style=\"color:#b10e2a\">${score(s.percentage)}</strong> &nbsp; ▾</span></summary><div class=\"accordionInner\"><p class=\"footnote\">The semester percentage is independent of the illustrative weekly unit fixtures below.</p>${!breakdown?.units?.length?'<div class=\"empty\">No enrolments mapped to this semester in the emulated data.</div>':breakdown.units.map(u=>`<details class=\"subAccordion\"><summary><span><strong>${escapeHtml(u.code)}</strong> · ${escapeHtml(u.name)}<div class=\"micro\">${u.semesterAssignment==='DEMO_CURRENT_ENROLMENT_ASSIGNMENT'?'Demo current enrolment mapping':'Matched emulated enrolment'} · Synthetic unit</div></span><span><strong>${score(u.percentage)}</strong> &nbsp; ▾</span></summary><div style=\"padding:14px\"><div class=\"formula\">Class and Lab are each worth 0.5. Both Present = 1.0; one Present = 0.5; both Absent = 0.0.</div><div class=\"tableWrap\" style=\"margin-top:13px\"><table class=\"table\"><thead><tr><th>Week</th><th>Class</th><th>Lab</th><th>Class Score</th><th>Lab Score</th><th>Week Score</th><th>Week %</th></tr></thead><tbody>${u.weeks.map(w=>`<tr><td>${w.week}</td><td>${badgePresence(w.classStatus)}</td><td>${badgePresence(w.labStatus)}</td><td>${w.classScore}</td><td>${w.labScore}</td><td><strong>${w.weekScore.toFixed(1)}</strong></td><td>${w.weekPercent}%</td></tr>`).join('')}</tbody></table></div><p class=\"footnote\">These 12 weeks are stable synthetic samples, not Qwickly records.</p></div></details>`).join('')}</div></details>`}).join('');\n return `<div class=\"row\" style=\"margin-bottom:14px\"><button class=\"icon-button\" data-open=\"students\">← Student Search</button><button class=\"icon-button\" data-open=\"attendance\">Attendance view</button><button class=\"icon-button\" data-open=\"visa\">Visa view</button><button class=\"icon-button\" data-open=\"reports\">Reports</button></div>`+panel(escapeHtml(p.fullName),gridFields(fields),`Student ID ${escapeHtml(p.sisId)} · Emulated student profile`)+panel('Semester attendance',terms,`Expand a semester, then a unit, to see 12 Class/Lab weekly records.`)+panel('Visa & compliance context',gridFields([['Applicable',p.visa.applicable?'Yes':'No'],['Status',p.visa.status],['Expiry date',p.visa.expiryDate||'Not available'],['Review required',p.visa.reviewRequired?'Yes':'No']])+`<p class=\"footnote\">${escapeHtml(p.visa.note)}</p>`,'Emulated student information only; not a visa or immigration assessment.')+panel('Student exports',`<div class=\"utility\"><button class=\"button\" data-download=\"academic\" data-sis=\"${p.sisId}\">Academic PDF</button><button class=\"button secondaryButton\" data-download=\"visa\" data-sis=\"${p.sisId}\">Visa PDF</button><button class=\"button secondaryButton\" data-download=\"compliance\" data-sis=\"${p.sisId}\">Compliance PDF</button><button class=\"button secondaryButton\" data-download=\"csv\" data-sis=\"${p.sisId}\">CSV</button><button class=\"button secondaryButton\" data-preview=\"${p.sisId}\">Print-ready preview</button></div>`,'All reports are distinct files, not combined.');\n}\nfunction settings(){return panel('Integration status',`<div class=\"tableWrap\"><table class=\"table\"><thead><tr><th>Component</th><th>Source</th><th>Status</th></tr></thead><tbody>${[\n['Admin login','NextAuth / Microsoft Entra from Next.js source','Not ported; protect webhook separately'],['Student profile','Original n8n profile emulator','Synthetic'],['Semester attendance','Synthetic deterministic replacement; original branch not supplied','Not Qwickly-verified'],['Unit / week breakdown','Original stable hash + 12 Class/Lab weeks','Synthetic fixtures'],['PDF','Native PDF binary built in n8n Code node','Separate draft PDFs'],['Excel','Native XLSX builder in n8n Code node','Six sheets']].map(([n,s,t])=>`<tr><td>${escapeHtml(n)}</td><td>${escapeHtml(s)}</td><td><span class=\"badge\">${escapeHtml(t)}</span></td></tr>`).join('')}</tbody></table></div>`)+panel('Deployment and data safety',`<p>Everything in this prototype runs in the imported n8n workflow; there is no Vercel or external PDF conversion service. The browser connects using an absolute webhook URL because n8n Cloud returns sandboxed HTML.</p><div class=\"formula\">Important: The original Microsoft Entra / NextAuth session is not included in this standalone version. Use only synthetic demo data until a proper administrative authentication layer is added.</div><p class=\"footnote\">The supplied Qwickly workflow also contains QR check-in experiments. This admin-only rebuild intentionally does not write attendance records.</p>`);}\nfunction render(){const st=$('stage');st.innerHTML=page==='dashboard'?overview():page==='student'?studentPage():page==='settings'?settings():workspace();bindActions();}\nfunction formError(msg){const e=$('formError');if(e){e.textContent=msg;e.style.display=msg?'block':'none';}}\nasync function getJson(url){const res=await fetch(url,{cache:'no-store'});const text=await res.text();let j;try{j=JSON.parse(text)}catch{throw Error('Unexpected API response. Make sure the n8n workflow is active.');}if(!res.ok||j.error)throw Error(j.error||`HTTP ${res.status}`);return j;}\nasync function lookup(){if(working)return;idsInput=$('ids').value;working=true;$('searchBtn').disabled=true;$('searchBtn').innerHTML='<span class=\"spinner\"></span> Searching...';formError('');try{const ids=[...new Set(idsInput.split(/[\\s,;]+/).map(s=>s.trim()).filter(Boolean))];if(!ids.length||ids.length>25||ids.some(s=>!/^\\d{6,12}$/.test(s)))throw Error('Enter 1–25 numeric SIS IDs, each 6–12 digits.');const j=await getJson(endpoint('batch',{ids:ids.join(',')}));results=j.results;$('resultArea').innerHTML=resultTable();bindActions();}catch(e){formError(e.message);}finally{working=false;const b=$('searchBtn');if(b){b.disabled=false;b.textContent='⌕  Search Students';}}}\nasync function loadStudent(id){$('stage').innerHTML='<div class=\"panel\"><span class=\"spinner\"></span> Loading student profile and semester details...</div>';selected=null;setPage('student');$('stage').innerHTML='<div class=\"panel\">Loading student profile and semesters…</div>';try{selected=await getJson(endpoint('student',{sis_id:id}));render();}catch(e){$('stage').innerHTML=panel('Student unavailable',`<p class=\"error\">${escapeHtml(e.message)}</p><button data-open=\"students\" class=\"button\">Back to search</button>`);bindActions();}}\nasync function downloadFile(action,params,name){const url=endpoint(action,params);try{const r=await fetch(url,{cache:'no-store'});if(!r.ok){let txt=await r.text();try{txt=JSON.parse(txt).error||txt}catch{}throw Error(txt);}const blob=await r.blob();const a=document.createElement('a');const blobUrl=URL.createObjectURL(blob);a.href=blobUrl;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(blobUrl),3000);}catch(e){alert('Download error: '+e.message+'\\nYou can also open the direct report URL in a browser.');}}\nfunction bindActions(){document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>go(x.dataset.open));document.querySelectorAll('[data-student]').forEach(x=>x.onclick=()=>loadStudent(x.dataset.student));document.querySelectorAll('[data-download]').forEach(x=>x.onclick=()=>{const t=x.dataset.download,id=x.dataset.sis;downloadFile(t==='csv'?'csv':'pdf',{sis_id:id,...(t!=='csv'?{type:t}:{})},t==='csv'?`FYP_attendance_${id}.csv`:`FYP_${t}_${id}_DRAFT.pdf`);});document.querySelectorAll('[data-preview]').forEach(x=>x.onclick=()=>{const id=x.dataset.preview;const layer=document.createElement('div');layer.className='preview-overlay';layer.innerHTML='<div class=\"preview-box\"><div class=\"preview-toolbar\"><strong>Academic attendance · Print-ready preview</strong><button type=\"button\" id=\"closePreview\">Close ✕</button></div><iframe title=\"Draft academic preview\"></iframe></div>';document.body.appendChild(layer);layer.querySelector('iframe').src=endpoint('preview',{sis_id:id});layer.querySelector('#closePreview').onclick=()=>layer.remove();layer.onclick=e=>{if(e.target===layer)layer.remove();};});const form=$('batchForm');if(form)form.onsubmit=e=>{e.preventDefault();lookup();};const excel=$('excelBtn');if(excel)excel.onclick=()=>{idsInput=$('ids').value;downloadFile('excel',{ids:idsInput},'Smart_Attendance_Admin_Demo.xlsx');};}\ndocument.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('menuBtn').onclick=()=>{$('sidebar').classList.toggle('sidebarOpen');$('backdrop').style.display=$('sidebar').classList.contains('sidebarOpen')?'block':'none'};$('backdrop').onclick=()=>{$('sidebar').classList.remove('sidebarOpen');$('backdrop').style.display='none'};\nsetPage(['dashboard','students','attendance','visa','reports','settings'].includes(initialPage)?initialPage:'dashboard');\nif(idsInput&&page!=='dashboard'&&page!=='settings')lookup();\n</script></body></html>\n";
const base=String(request.webhookUrl||'https://fyp-workflow.swin.click/webhook/fyp/admin').split('?')[0];
function renderPortal(){return FRONTEND.replace('__BASE_URL__',JSON.stringify(base)).replace('__INITIAL_PAGE__',JSON.stringify(String(query.page||'dashboard'))).replace('__INITIAL_IDS__',JSON.stringify(String(query.ids||'')));}
function html(body,status=200){return [{json:{kind:'html',body,status}}];}
function json(payload,status=200){return [{json:{kind:'json',payload,status}}];}
function file(buffer,mimeType,filename){return [{json:{kind:'file',status:200,mimeType,filename},binary:{file:{data:buffer.toString('base64'),mimeType,fileName:filename,fileExtension:filename.split('.').at(-1)}}}];}
