{name:'Full Attendance Logs',headers:['Course LMS ID','Course Code','Course Name','Session ID','Session Title','Session Start','Method','Record ID','Qwickly User ID','SIS ID','Student Name','Student Email','Attendance Status','Status ID','Record Timestamp','Check-in Method','Raw Qwickly Record JSON'],rows},
{name:'Session Index',headers:['Session ID','Title','Start Time','Method'],rows:sessions.map(s=>[s.sessionId,s.title,s.startTime,s.method])},
{name:'Course Enrolments',headers:['Qwickly User ID','SIS ID','Student Name','Email'],rows:enrolled.map(u=>[u.id??u.user_id??'',u.sis_id??'',`${u.first_name??''} ${u.last_name??''}`.trim(),u.email??''])},
